package main

import (
	"context"
	"time"
)

// Honors cancellation: stops promptly and reports why.
func process(ctx context.Context, items []int, do func(int)) error {
	for _, it := range items {
		select {
		case <-ctx.Done():
			return ctx.Err() // context.Canceled or DeadlineExceeded
		case <-time.After(50 * time.Millisecond): // simulated work
			do(it)
		}
	}
	return nil
}

