package solution

import (
	"context"
	"errors"
)

func FirstResult(ctx context.Context, calls []func(context.Context) (string, error)) (string, error) {
	if len(calls) == 0 {
		return "", errors.New("no calls")
	}
	// Child context we can cancel as soon as we have a winner.
	ctx, cancel := context.WithCancel(ctx)
	defer cancel() // cancels all still-running calls on return

	type result struct {
		val string
		err error
	}
	results := make(chan result, len(calls)) // buffered so late senders don't block/leak
	for _, call := range calls {
		call := call // capture per iteration
		go func() {
			v, err := call(ctx) // pass the cancellable ctx down
			results <- result{v, err}
		}()
	}

	var lastErr error
	for i := 0; i < len(calls); i++ {
		r := <-results
		if r.err == nil {
			return r.val, nil // first success; defer cancel() stops the rest
		}
		lastErr = r.err
	}
	return "", lastErr // all failed
}

