package solution

import (
	"context"
	"errors"
	"testing"
	"time"
)

func TestFirstResult_Success(t *testing.T) {
	calls := []func(context.Context) (string, error){
		func(ctx context.Context) (string, error) {
			select {
			case <-time.After(100 * time.Millisecond):
				return "slow", nil
			case <-ctx.Done():
				return "", ctx.Err()
			}
		},
		func(ctx context.Context) (string, error) { return "fast", nil },
	}
	got, err := FirstResult(context.Background(), calls)
	if err != nil || got != "fast" {
		t.Fatalf("got %q/%v want fast/nil", got, err)
	}
}

func TestFirstResult_AllFail(t *testing.T) {
	boom := errors.New("boom")
	calls := []func(context.Context) (string, error){
		func(ctx context.Context) (string, error) { return "", boom },
		func(ctx context.Context) (string, error) { return "", boom },
	}
	if _, err := FirstResult(context.Background(), calls); !errors.Is(err, boom) {
		t.Fatalf("want boom, got %v", err)
	}
}

