func handler(w http.ResponseWriter, r *http.Request) {
	ctx, cancel := context.WithTimeout(r.Context(), time.Second)
	defer cancel()
	rows, err := db.QueryContext(ctx, "SELECT * FROM big_table") // ctx threaded in
	if err != nil {
		http.Error(w, err.Error(), http.StatusGatewayTimeout)
		return
	}
	defer rows.Close()
	// ... now the query is cancelled when the deadline fires or client leaves ...
}

func DoWithTimeout(parent context.Context, d time.Duration, work func(context.Context) (int, error)) (int, error) {
	ctx, cancel := context.WithTimeout(parent, d)
	defer cancel() // release timer; also signals work to stop

	type res struct {
		n   int
		err error
	}
	ch := make(chan res, 1) // buffered: goroutine can send & exit even after timeout
	go func() {
		n, err := work(ctx) // work should honor ctx too
		ch <- res{n, err}
	}()

	select {
	case r := <-ch:
		return r.n, r.err
	case <-ctx.Done():
		return 0, ctx.Err() // DeadlineExceeded (or Canceled if parent cancelled)
	}
}
